extends Sprite2D

var station_position: Vector2 = Vector2(600, 300)
var speed: float = 120.0
var shield: float = 20.0
var shield_rate: float = 15.0


func _ready() -> void:
	modulate = Color.CYAN


func _process(delta: float) -> void:
	if position.x < station_position.x:
		position.x += speed * delta
	elif position.x > station_position.x:
		position.x -= speed * delta
	var diff: float = abs(position.x - station_position.x)
	if diff < 10.0:
		modulate = Color.GREEN
	else:
		modulate = Color.CYAN
	shield += shield_rate * delta
	shield = clamp(shield, 0.0, 100.0)

extends Sprite2D

var station_position: Vector2 = Vector2(600, 300)
var speed: float = 120.0
var shield: float = 20.0
var shield_rate: float = 15.0


func _ready() -> void:
	modulate = Color.CYAN


func _process(delta: float) -> void:
	move_toward_station(delta)
	if is_near_station(station_position.x):
		modulate = Color.GREEN
	else:
		modulate = Color.CYAN
	update_shield(delta)


func move_toward_station(delta: float) -> void:
	if position.x < station_position.x:
		position.x += speed * delta
	elif position.x > station_position.x:
		position.x -= speed * delta


func is_near_station(station_x: float) -> bool:
	var diff: float = abs(position.x - station_x)
	return diff < 10.0


func update_shield(delta: float) -> void:
	shield += shield_rate * delta
	shield = clamp(shield, 0.0, 100.0)

